const Charges: React.FC<{ cx: number; cy: number; k: number }> = ({ cx, cy, k }) => (
  <>{Array.from({ length: 10 }, (_, i) => { const a = (i / 10) * Math.PI * 2, d = 420 - 300 * k; return <div key={i} style={{ position: "absolute", left: cx + Math.cos(a) * d - 26, top: cy + Math.sin(a) * d - 26, width: 52, height: 52, borderRadius: 99, background: CYAN, border: `4px solid ${INK}`, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: FONT.head, fontWeight: 700, fontSize: 38, color: INK, opacity: 1 - 0.8 * Math.max(0, k - 0.8) / 0.2 }}>−</div>; })}</>
);
const Spiral: React.FC<{ cx: number; cy: number; r: number; color?: string }> = ({ cx, cy, r, color = VIOLET }) => {
  const { f } = useC();
  const t = f / 30;
  return <Svg x={cx - r} y={cy - r} w={r * 2} h={r * 2}>{[0, 1, 2, 3].map((i) => { const a0 = t * 1.4 + (i * Math.PI) / 2; const pts = Array.from({ length: 30 }, (_, j) => { const u = j / 29, a = a0 + u * 3.2, rr2 = r * (1 - u * 0.85); return `${r + Math.cos(a) * rr2},${r + Math.sin(a) * rr2 * 0.55}`; }).join(" "); return <polyline key={i} points={pts} fill="none" stroke={color} strokeWidth={8} strokeLinecap="round" opacity={0.85} />; })}</Svg>;
};

